SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ----------------------------
-- Table structure for config_info
-- ----------------------------
DROP TABLE IF EXISTS `config_info`;
CREATE TABLE `config_info`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `data_id` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL COMMENT 'data_id',
  `group_id` varchar(128) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT 'group_id',
  `content` longtext CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL COMMENT 'content',
  `md5` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT 'md5',
  `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `gmt_modified` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  `src_user` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT 'source user',
  `src_ip` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT 'source ip',
  `app_name` varchar(128) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT 'app_name',
  `tenant_id` varchar(128) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT '' COMMENT '租户字段',
  `c_desc` varchar(256) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT 'configuration description',
  `c_use` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT 'configuration usage',
  `effect` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT '配置生效的描述',
  `type` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT '配置的类型',
  `c_schema` text CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL COMMENT '配置的模式',
  `encrypted_data_key` varchar(1024) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL DEFAULT '' COMMENT '密钥',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_configinfo_datagrouptenant`(`data_id` ASC, `group_id` ASC, `tenant_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 281 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_bin COMMENT = 'config_info' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of config_info
-- ----------------------------
INSERT INTO `config_info` VALUES (1, 'application-dev.yml', 'DEFAULT_GROUP', '# spring:\n#   autoconfigure:\n#     exclude: com.alibaba.druid.spring.boot.autoconfigure.DruidDataSourceAutoConfigure\n    # exclude: org.springframework.boot.autoconfigure.jdbc.DataSourceAutoConfiguration\n# feign 配置\nfeign:\n  sentinel:\n    enabled: true\n  okhttp:\n    enabled: true\n  httpclient:\n    enabled: false\n  client:\n    config:\n      default:\n        connectTimeout: 10000\n        readTimeout: 10000\n  compression:\n    request:\n      enabled: true\n      min-request-size: 8192\n    response:\n      enabled: true\n\n\n# Seata 配置\nseata:\n  registry:\n    type: nacos\n    nacos:\n      application: seata-server\n      server-addr: localhost:8848\n      namespace: \"\"\n      group: DEFAULT_GROUP\n      username: nacos\n      password: nacos\n    tx-service-group: smart-live\n    service: \n      vgroup-mapping:\n         smart-live: \"default\"\n  data-source-proxy-mode: XA #开启数据源代理的XA模式\n\n# 暴露监控端点\nmanagement:\n  endpoints:\n    web:\n      exposure:\n        include: \'*\'', 'e0983cbead3ad0f16674c5af76de2483', '2020-05-20 12:00:00', '2025-12-25 03:44:01', 'nacos', '0:0:0:0:0:0:0:1', '', '', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` VALUES (2, 'smartLive-gateway-dev.yml', 'DEFAULT_GROUP', 'spring:\n  redis:\n    host: 127.0.0.1\n    port: 6379\n    password: \n  cloud:\n    sentinel:\n      enabled: true\n      transport:\n        dashboard: localhost:8718  #sentinel的控制台地址\n        port: 8719\n    gateway:\n      discovery:\n        locator:\n          lowerCaseServiceId: true\n          enabled: true\n      routes:\n        # 认证中心\n        - id: smartLive-auth\n          uri: lb://smartLive-auth\n          predicates:\n            - Path=/admin/auth/**,/app/auth/**\n          filters:\n            # 验证码处理\n            - CacheRequestBody\n            - ValidateCodeFilter\n            - StripPrefix=2\n        # 代码生成\n        - id: smartLive-gen\n          uri: lb://smartLive-gen\n          predicates:\n            - Path=/admin/code/**\n          filters:\n            - StripPrefix=2\n        # 定时任务\n        - id: smartLive-job\n          uri: lb://smartLive-job\n          predicates:\n            - Path=/admin/schedule/**\n          filters:\n            - StripPrefix=2\n        # 系统模块\n        - id: smartLive-system\n          uri: lb://smartLive-system\n          predicates:\n            - Path=/admin/system/**\n          filters:\n            - StripPrefix=2\n          #首页模块\n        - id: smartLive-index\n          uri: lb://smartLive-index\n          predicates:\n            - Path=/admin/index/**\n          filters:\n            - StripPrefix=2\n        # 文件服务\n        - id: smartLive-file\n          uri: lb://smartLive-file\n          predicates:\n            - Path=/app/file/**,/admin/file/**\n          filters:\n            - StripPrefix=2\n          # 商铺模块\n        - id: smartLive-shop\n          uri: lb://smartLive-shop\n          predicates:\n            - Path=/admin/shop/**,/app/shop/**\n          filters:\n            - StripPrefix=1\n          # 商品模块\n        - id: smartLive-product\n          uri: lb://smartLive-product\n          predicates:\n            - Path=/admin/product/**,/app/product/**\n          filters:\n            - StripPrefix=1\n          #  博客模块\n        - id: smartLive-blog\n          uri: lb://smartLive-blog\n          predicates:\n            - Path=/admin/blog/**,/app/blog/**\n          filters:\n            - StripPrefix=1\n          #  订单模块\n        - id: smartLive-order\n          uri: lb://smartLive-order\n          predicates:\n            - Path=/admin/order/**,/app/order/**\n          filters:\n            - StripPrefix=1\n          #  用户模块\n        - id: smartLive-user\n          uri: lb://smartLive-user\n          predicates:\n            - Path=/admin/user/**,/app/user/**\n          filters:\n            - StripPrefix=1\n          #  ai模块\n        - id: smartLive-ai\n          uri: lb://smartLive-ai\n          predicates:\n            - Path=/admin/ai/**,/app/ai/**\n          filters:\n            - StripPrefix=2\n         #  私聊模块\n        - id: smartLive-chat    \n          uri: lb://smartLive-chat\n          predicates:\n            - Path=/app/chat/**\n          filters:\n            - StripPrefix=2\n             #搜索模块\n        - id: smartLive-search\n          uri: lb://smartLive-search\n          predicates:\n            - Path=/app/search/**\n          filters:\n            - StripPrefix=1\n           #  互动模块\n        - id: smartLive-interaction \n          uri: lb://smartLive-interaction\n          predicates:\n            - Path=/app/interaction/**,/admin/interaction/**\n          filters:\n            - StripPrefix=2\n             #  审核模块\n        - id: smartLive-audit \n          uri: lb://smartLive-audit\n          predicates:\n            - Path=/admin/audit/**\n          filters:\n            - StripPrefix=1\n             #  积分模块\n        - id: smartLive-points \n          uri: lb://smartLive-points\n          predicates:\n            - Path=/app/points/**,/admin/points/**\n          filters:\n            - StripPrefix=1\n             #  积分模块\n        - id: smartLive-wallet \n          uri: lb://smartLive-wallet\n          predicates:\n            - Path=/app/wallet/**,/admin/wallet/**,/app/pay/**\n          filters:\n            - StripPrefix=1\n# 安全配置\nsecurity:\n  # 验证码\n  captcha:\n    enabled: true\n    type: math\n  # 防止XSS攻击\n  xss:\n    enabled: true\n    excludeUrls:\n      - /system/notice\n\n  # 不校验白名单\n  ignore:\n  # 管理端放行接口\n    adminWhites:\n      - /admin/auth/logout\n      - /admin/auth/login\n      - /admin/auth/register\n      - /*/v2/api-docs\n      - /*/v3/api-docs\n      - /csrf\n  # App端放行接口\n    appWhites:\n      - /app/auth/appLogin\n      - /app/auth/appLoginByPassword\n      - /app/shop/**\n      - /app/shop-type/**\n      - /app/product/getProductById\n      - /app/blog/**\n      - /app/upload/**\n      - /app/user/stats/*\n      - /app/user/info/getUserInfo/*\n      - /app/search/**\n      - /app/chat/ws/chat\n      - /app/interaction/like/likeUserList\n      - /app/interaction/comment/listComment\n      - /app/interaction/comment/listChildComment\n      - /app/interaction/review/listReview\n      - /app/interaction/follow/follows\n      - /app/interaction/follow/fans\n      - /app/interaction/like/likeRecord\n      - /app/interaction/star/starList\n      - /app/interaction/star/isStar\n# springdoc配置\nspringdoc:\n  webjars:\n    # 访问前缀\n    prefix:\n', '753f98c723b124d55fa24ce8279acce5', '2020-05-14 14:17:55', '2026-03-09 03:26:32', 'nacos', '0:0:0:0:0:0:0:1', '', '', '', '', '', 'yaml', '', '');
