INSERT INTO `config_info` VALUES (56, 'smartLive-user-dev.yml', 'DEFAULT_GROUP', 'spring:\n  redis:\n    host: 127.0.0.1\n    port: 6379\n    password:   # 空密码就留空\n    database: 0\n\n  datasource:\n    dynamic:\n      primary: master                                          # 默认主数据源\n      strict: false                                            # 可选：切换不存在的数据源时不报错\n      datasource:\n        master:\n          driver-class-name: com.mysql.cj.jdbc.Driver\n          url: jdbc:mysql://127.0.0.1:3306/smart-live_user?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n          username: root\n          password: 123167\n          # Druid 连接池参数（全部放在这里）\n          druid:\n            initial-size: 5\n            min-idle: 5\n            max-active: 20\n            max-wait: 60000\n            time-between-eviction-runs-millis: 60000\n            min-evictable-idle-time-millis: 300000\n            validation-query: SELECT 1 FROM DUAL\n            test-while-idle: true\n            test-on-borrow: false\n            test-on-return: false\n            pool-prepared-statements: true\n            max-pool-prepared-statement-per-connection-size: 20\n            filters: stat,slf4j\n            connection-properties: druid.stat.mergeSql=true;druid.stat.slowSqlMillis=5000\n\n    # Druid 监控页面配置（保留在外面）\n    druid:\n      stat-view-servlet:\n        enabled: true\n        login-username: ruoyi\n        login-password: 123456\n\n# mybatis 配置（你原来的，保持不变）\nmybatis:\n  type-aliases-package: com.smartLive.user.domain\n  mapper-locations: classpath:mapper/**/*.xml\n\n# mybatis-plus 配置\nmybatis-plus:\n  type-aliases-package: com.smartLive.user.domain\n\n# SpringDoc 等其他配置保持不变\nspringdoc:\n  gateway-url: http://localhost:8080/${spring.application.name}\n  api-docs:\n    enabled: true\n  info:\n    title: \'系统模块接口文档\'\n    description: \'系统模块接口描述\'\n    contact:\n      name: RuoYi\n      url: https://ruoyi.vip', '76156678ddfdfe1641b8299f2236a036', '2025-09-21 15:16:56', '2025-12-25 07:35:06', 'nacos', '0:0:0:0:0:0:0:1', '', '', '', '', '', 'yaml', '', '');
