INSERT INTO `config_info` VALUES (275, 'xxl-job-common.yml', 'DEFAULT_GROUP', 'xxl:\r\n  job:\r\n    admin:\r\n      # 调度中心的统一地址\r\n      addresses: http://192.168.182.20:8080/xxl-job-admin\r\n    accessToken: default_token\r\n    executor:\r\n      # 【神级配置1】动态读取引入该配置的微服务的名字作为执行器名字\r\n      appname: ${spring.application.name}\r\n      # 【神级配置2】配置为 -1，表示自动分配可用端口，彻底解决多个服务端口冲突问题！\r\n      port: -1\r\n      # 统一的日志路径，按服务名分目录\r\n      logpath: /data/applogs/xxl-job/${spring.application.name}\r\n      logretentiondays: 30', '86bdd281a938a8deaa5cba2bdd5f20ab', '2026-02-22 11:59:03', '2026-02-22 11:59:03', NULL, '0:0:0:0:0:0:0:1', '', '', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` VALUES (279, 'rabbitmq-common.yml', 'DEFAULT_GROUP', 'spring:\n  rabbitmq:\n    host: 192.168.182.20\n    port: 5672\n    username: smart-live\n    password: 123167\n    virtual-host: smart-live', '34f57564bcff59cbafe993e3c4a201bc', '2026-03-18 19:14:36', '2026-03-20 13:23:45', 'nacos', '0:0:0:0:0:0:0:1', '', '', 'RabbitMQ 公共连接配置', '供所有依赖 RabbitMQ 的微服务统一引用', '发布后立即生效', 'yaml', '', '');

