INSERT INTO `his_config_info` VALUES (2, 241, 'smartLive-gateway-dev.yml', 'DEFAULT_GROUP', '', 'spring:\n  redis:\n    host: 127.0.0.1\n    port: 6379\n    password: \n  cloud:\n    sentinel:\n      enabled: true\n      transport:\n        dashboard: localhost:8718  #sentinel的控制台地址\n        port: 8719\n    gateway:\n      discovery:\n        locator:\n          lowerCaseServiceId: true\n          enabled: true\n      routes:\n        # 认证中心\n        - id: smartLive-auth\n          uri: lb://smartLive-auth\n          predicates:\n            - Path=/admin/auth/**,/app/auth/**\n          filters:\n            # 验证码处理\n            - CacheRequestBody\n            - ValidateCodeFilter\n            - StripPrefix=2\n        # 代码生成\n        - id: smartLive-gen\n          uri: lb://smartLive-gen\n          predicates:\n            - Path=/admin/code/**\n          filters:\n            - StripPrefix=2\n        # 定时任务\n        - id: smartLive-job\n          uri: lb://smartLive-job\n          predicates:\n            - Path=/admin/schedule/**\n          filters:\n            - StripPrefix=2\n        # 系统模块\n        - id: smartLive-system\n          uri: lb://smartLive-system\n          predicates:\n            - Path=/admin/system/**\n          filters:\n            - StripPrefix=2\n          #首页模块\n        - id: smartLive-index\n          uri: lb://smartLive-index\n          predicates:\n            - Path=/admin/index/**\n          filters:\n            - StripPrefix=2\n        # 文件服务\n        - id: smartLive-file\n          uri: lb://smartLive-file\n          predicates:\n            - Path=/app/file/**,/admin/file/**\n          filters:\n            - StripPrefix=2\n          # 商铺模块\n        - id: smartLive-shop\n          uri: lb://smartLive-shop\n          predicates:\n            - Path=/admin/shop/**,/app/shop/**\n          filters:\n            - StripPrefix=1\n          # 商品模块\n        - id: smartLive-product\n          uri: lb://smartLive-product\n          predicates:\n            - Path=/admin/product/**,/app/product/**\n          filters:\n            - StripPrefix=1\n          #  博客模块\n        - id: smartLive-blog\n          uri: lb://smartLive-blog\n          predicates:\n            - Path=/admin/blog/**,/app/blog/**\n          filters:\n            - StripPrefix=1\n          #  订单模块\n        - id: smartLive-order\n          uri: lb://smartLive-order\n          predicates:\n            - Path=/admin/order/**,/app/order/**\n          filters:\n            - StripPrefix=1\n          #  用户模块\n        - id: smartLive-user\n          uri: lb://smartLive-user\n          predicates:\n            - Path=/admin/user/**,/app/user/**\n          filters:\n            - StripPrefix=1\n          #  ai模块\n        - id: smartLive-ai\n          uri: lb://smartLive-ai\n          predicates:\n            - Path=/admin/ai/**,/app/ai/**\n          filters:\n            - StripPrefix=2\n         #  私聊模块\n        - id: smartLive-chat    \n          uri: lb://smartLive-chat\n          predicates:\n            - Path=/app/chat/**\n          filters:\n            - StripPrefix=2\n             #搜索模块\n        - id: smartLive-search\n          uri: lb://smartLive-search\n          predicates:\n            - Path=/app/search/**\n          filters:\n            - StripPrefix=1\n           #  互动模块\n        - id: smartLive-interaction \n          uri: lb://smartLive-interaction\n          predicates:\n            - Path=/app/interaction/**,/admin/interaction/**\n          filters:\n            - StripPrefix=2\n             #  审核模块\n        - id: smartLive-audit \n          uri: lb://smartLive-audit\n          predicates:\n            - Path=/admin/audit/**\n          filters:\n            - StripPrefix=1\n             #  积分模块\n        - id: smartLive-points \n          uri: lb://smartLive-points\n          predicates:\n            - Path=/app/points/**,/admin/points/**\n          filters:\n            - StripPrefix=1\n             #  积分模块\n        - id: smartLive-wallet \n          uri: lb://smartLive-wallet\n          predicates:\n            - Path=/app/wallet/**,/admin/wallet/**,/app/pay/**\n          filters:\n            - StripPrefix=1\n# 安全配置\nsecurity:\n  # 验证码\n  captcha:\n    enabled: true\n    type: math\n  # 防止XSS攻击\n  xss:\n    enabled: true\n    excludeUrls:\n      - /system/notice\n\n  # 不校验白名单\n  ignore:\n  # 管理端放行接口\n    adminWhites:\n      - /admin/auth/logout\n      - /admin/auth/login\n      - /admin/auth/register\n      - /*/v2/api-docs\n      - /*/v3/api-docs\n      - /csrf\n  # App端放行接口\n    appWhites:\n      - /app/auth/appLogin\n      - /app/auth/appLoginByPassword\n      - /app/shop/**\n      - /app/shop-type/**\n      - /app/marketing/**\n      - /app/blog/**\n      - /app/upload/**\n      - /app/user/stats/*\n      - /app/user/info/getUserInfo/*\n      - /app/search/**\n      - /app/chat/ws/chat\n      - /app/interaction/like/likeUserList\n      - /app/interaction/comment/listComment\n      - /app/interaction/comment/listChildComment\n      - /app/interaction/review/listReview\n      - /app/interaction/follow/follows\n      - /app/interaction/follow/fans\n      - /app/interaction/like/likeRecord\n      - /app/interaction/star/starList\n      - /app/interaction/star/isStar\n# springdoc配置\nspringdoc:\n  webjars:\n    # 访问前缀\n    prefix:\n', 'd4f20a66bc69674414b9bf0f9511a4ce', '2026-03-09 11:26:32', '2026-03-09 03:26:32', 'nacos', '0:0:0:0:0:0:0:1', 'U', '', '', 'formal', NULL, NULL);
INSERT INTO `his_config_info` VALUES (270, 242, 'smartLive-product-dev.yml', 'DEFAULT_GROUP', '', '# spring配置\nspring:\n  redis:\n    host: 127.0.0.1\n    port: 6379\n    password: \n  datasource:\n    druid:\n      stat-view-servlet:\n        enabled: true\n        loginUsername: ruoyi\n        loginPassword: 123456\n    dynamic:\n      druid:\n        initial-size: 5\n        min-idle: 5\n        maxActive: 20\n        maxWait: 60000\n        connectTimeout: 30000\n        socketTimeout: 60000\n        timeBetweenEvictionRunsMillis: 60000\n        minEvictableIdleTimeMillis: 300000\n        validationQuery: SELECT 1 FROM DUAL\n        testWhileIdle: true\n        testOnBorrow: false\n        testOnReturn: false\n        poolPreparedStatements: true\n        maxPoolPreparedStatementPerConnectionSize: 20\n        filters: stat,slf4j\n        connectionProperties: druid.stat.mergeSql\\=true;druid.stat.slowSqlMillis\\=5000\n      datasource:\n          # 主库数据源\n          master:\n            driver-class-name: com.mysql.cj.jdbc.Driver\n            url: jdbc:mysql://127.0.0.1:3306/smart-live_marketing?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n            username: root\n            password: 123167\n          # 从库数据源\n          # slave:\n            # username: \n            # password: \n            # url: \n            # driver-class-name: \n\n# mybatis配置\nmybatis:\n    # 搜索指定包别名\n    typeAliasesPackage: com.smartLive.marketing\n    # 配置mapper的扫描，找到所有的mapper.xml映射文件\n    mapperLocations: classpath:mapper/**/*.xml\n\nmybatis-plus:\n  type-aliases-package: com.smartLive.marketing \n# springdoc配置\nspringdoc:\n  gatewayUrl: http://localhost:8080/${spring.application.name}\n  api-docs:\n    # 是否开启接口文档\n    enabled: true\n  info:\n    # 标题\n    title: \'系统模块接口文档\'\n    # 描述\n    description: \'系统模块接口描述\'\n    # 作者信息\n    contact:\n      name: RuoYi\n      url: https://ruoyi.vip\n', '4d5d6d1752269df904e3946cf7feb0ae', '2026-03-13 18:15:32', '2026-03-13 10:15:32', 'nacos', '0:0:0:0:0:0:0:1', 'U', '', '', 'formal', NULL, NULL);
INSERT INTO `his_config_info` VALUES (270, 243, 'smartLive-product-dev.yml', 'DEFAULT_GROUP', '', '# spring配置\nspring:\n  redis:\n    host: 127.0.0.1\n    port: 6379\n    password: \n  datasource:\n    druid:\n      stat-view-servlet:\n        enabled: true\n        loginUsername: ruoyi\n        loginPassword: 123456\n    dynamic:\n      druid:\n        initial-size: 5\n        min-idle: 5\n        maxActive: 20\n        maxWait: 60000\n        connectTimeout: 30000\n        socketTimeout: 60000\n        timeBetweenEvictionRunsMillis: 60000\n        minEvictableIdleTimeMillis: 300000\n        validationQuery: SELECT 1 FROM DUAL\n        testWhileIdle: true\n        testOnBorrow: false\n        testOnReturn: false\n        poolPreparedStatements: true\n        maxPoolPreparedStatementPerConnectionSize: 20\n        filters: stat,slf4j\n        connectionProperties: druid.stat.mergeSql\\=true;druid.stat.slowSqlMillis\\=5000\n      datasource:\n          # 主库数据源\n          master:\n            driver-class-name: com.mysql.cj.jdbc.Driver\n            url: jdbc:mysql://127.0.0.1:3306/smart-live_product?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n            username: root\n            password: 123167\n          # 从库数据源\n          # slave:\n            # username: \n            # password: \n            # url: \n            # driver-class-name: \n\n# mybatis配置\nmybatis:\n    # 搜索指定包别名\n    typeAliasesPackage: com.smartLive.marketing\n    # 配置mapper的扫描，找到所有的mapper.xml映射文件\n    mapperLocations: classpath:mapper/**/*.xml\n\nmybatis-plus:\n  type-aliases-package: com.smartLive.marketing \n# springdoc配置\nspringdoc:\n  gatewayUrl: http://localhost:8080/${spring.application.name}\n  api-docs:\n    # 是否开启接口文档\n    enabled: true\n  info:\n    # 标题\n    title: \'系统模块接口文档\'\n    # 描述\n    description: \'系统模块接口描述\'\n    # 作者信息\n    contact:\n      name: RuoYi\n      url: https://ruoyi.vip\n', '133f83b660fca5882520c9d4f7df2534', '2026-03-13 18:15:38', '2026-03-13 10:15:38', 'nacos', '0:0:0:0:0:0:0:1', 'U', '', '', 'formal', NULL, NULL);
INSERT INTO `his_config_info` VALUES (279, 244, 'rabbitmq-common.yml', 'DEFAULT_GROUP', '', 'spring:\n  rabbitmq:\n    host: 8.134.81.22\n    port: 5672\n    username: smart-live\n    password: 123167\n    virtual-host: smart-live', '6ff2b6f9f2db7505212cd86defc44f0d', '2026-03-20 21:23:45', '2026-03-20 13:23:45', 'nacos', '0:0:0:0:0:0:0:1', 'U', '', '', 'formal', NULL, NULL);

-- ----------------------------
-- Table structure for permissions
-- ----------------------------
DROP TABLE IF EXISTS `permissions`;
CREATE TABLE `permissions`  (
  `role` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'role',
  `resource` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'resource',
  `action` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'action',
  UNIQUE INDEX `uk_role_permission`(`role` ASC, `resource` ASC, `action` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of permissions
-- ----------------------------

-- ----------------------------
-- Table structure for roles
-- ----------------------------
DROP TABLE IF EXISTS `roles`;
CREATE TABLE `roles`  (
  `username` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'username',
  `role` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'role',
  UNIQUE INDEX `idx_user_role`(`username` ASC, `role` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of roles
-- ----------------------------
INSERT INTO `roles` VALUES ('nacos', 'ROLE_ADMIN');

-- ----------------------------
-- Table structure for tenant_capacity
-- ----------------------------
DROP TABLE IF EXISTS `tenant_capacity`;
CREATE TABLE `tenant_capacity`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `tenant_id` varchar(128) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL DEFAULT '' COMMENT 'Tenant ID',
  `quota` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '配额，0表示使用默认值',
  `usage` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '使用量',
  `max_size` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '单个配置大小上限，单位为字节，0表示使用默认值',
  `max_aggr_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '聚合子配置最大个数',
  `max_aggr_size` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '单个聚合数据的子配置大小上限，单位为字节，0表示使用默认值',
  `max_history_count` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '最大变更历史数量',
  `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `gmt_modified` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_tenant_id`(`tenant_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_bin COMMENT = '租户容量信息表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of tenant_capacity
-- ----------------------------

-- ----------------------------
-- Table structure for tenant_info
-- ----------------------------
DROP TABLE IF EXISTS `tenant_info`;
CREATE TABLE `tenant_info`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `kp` varchar(128) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL COMMENT 'kp',
  `tenant_id` varchar(128) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT '' COMMENT 'tenant_id',
  `tenant_name` varchar(128) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT '' COMMENT 'tenant_name',
  `tenant_desc` varchar(256) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT 'tenant_desc',
  `create_source` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NULL DEFAULT NULL COMMENT 'create_source',
  `gmt_create` bigint NOT NULL COMMENT '创建时间',
  `gmt_modified` bigint NOT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_tenant_info_kptenantid`(`kp` ASC, `tenant_id` ASC) USING BTREE,
  INDEX `idx_tenant_id`(`tenant_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb3 COLLATE = utf8mb3_bin COMMENT = 'tenant_info' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of tenant_info
-- ----------------------------

-- ----------------------------
-- Table structure for users
-- ----------------------------
DROP TABLE IF EXISTS `users`;
CREATE TABLE `users`  (
  `username` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'username',
  `password` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'password',
  `enabled` tinyint(1) NOT NULL COMMENT 'enabled',
  PRIMARY KEY (`username`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of users
-- ----------------------------
INSERT INTO `users` VALUES ('nacos', '$2a$10$EuWPZHzz32dJN7jexM34MOeYirDdFAZm2kuWj7VEOJhhZkDrxfvUu', 1);

